const isUndiscoveredZone=z=>z?.source==='population_path_reference';
// Preserve the single field-map renderer; add source labels after each pan/zoom redraw.
class HuntFieldMap extends FieldMap{
 draw(){
  super.draw();
  const zones=new Map((this.data?.zones||[]).concat(this.data?.routeZones||[]).map(z=>[z.id,z]));
  for(const marker of this.svg.querySelectorAll('g[data-zone]')){
   const hidden=isUndiscoveredZone(zones.get(marker.dataset.zone));
   marker.dataset.discovery=hidden?'undiscovered':'known';
   if(hidden){
    marker.setAttribute('aria-label',(marker.getAttribute('aria-label')||'Zone')+', undiscovered reference area, not a live animal location');
    const title=marker.querySelector('title');if(title)title.textContent+=' · Undiscovered reference area';
   }
  }
 }
}
