function updateHuntStatus(){if(!state)return;const notice=$('#huntNotice'),message=warning();if(notice&&notice.innerHTML!==message)notice.innerHTML=message;
 const discovery=$('#zoneDiscovery');if(discovery){const markup=filters.species==='all'||huntSpeciesError?'':huntSpeciesLoading?'<p class="small muted">Loading zones for this animal…</p>':zoneDiscoveryNotice(state);if(discovery.innerHTML!==markup){const expanded=discovery.querySelector('details')?.open;discovery.innerHTML=markup;if(expanded&&discovery.querySelector('details'))discovery.querySelector('details').open=true;}}
const node=$('#sourceTime');if(node){const source=state.observer.sources.find(x=>x.name===`animal_population_${reserve}`);node.textContent=source?'Saved '+ago(source.mtime):'Waiting for game save';node.title=source?'Population save: '+date(source.mtime):'No population save has been read';}}
