function filteredZones(){
 if(filters.species==='all'||huntSpeciesLoading||huntSpeciesError)return [];
 const search=filters.search.trim().toLowerCase();
 const zones=huntZonesForSpecies(state.zones,filters.species).filter(z=>(filters.need==='all'||z.need===filters.need)&&(filters.strategy==='all'||(z.annotation?.strategy||'unassigned')===filters.strategy)&&(filters.time==='all'||(z.start<=z.end?(Number(filters.time)>=z.start&&Number(filters.time)<z.end):(Number(filters.time)>=z.start||Number(filters.time)<z.end)))&&(!search||[z.species,z.annotation?.name,z.annotation?.notes,Math.round(z.x),Math.round(z.z)].join(' ').toLowerCase().includes(search)));
 return zones.sort((a,b)=>filters.sort==='males'?(b.males??-1)-(a.males??-1)||a.species.localeCompare(b.species):filters.sort==='species'?a.species.localeCompare(b.species):Number(state.route.includes(b.id))-Number(state.route.includes(a.id))||(b.males??-1)-(a.males??-1)||a.id.localeCompare(b.id));
}
function huntSpeciesOptions(){const values=Array.isArray(state.huntSpeciesOptions)?state.huntSpeciesOptions:state.zones.map(z=>z.species);return [...new Set(values.filter(name=>typeof name==='string'&&name&&name!=='all'))].sort();}
function filterMarkup(){return `<div class="hunt-filters"><label>Animal<select id="filterSpecies">${options([['all','Choose an animal'],...huntSpeciesOptions()],filters.species)}</select></label><label>Activity<select id="filterNeed">${options([['all','Any activity'],['drinking','Drinking'],['feeding','Feeding'],['resting','Resting']],filters.need)}</select></label><details class="advanced-filters"><summary title="More filters">More filters</summary><div class="advanced-filter-fields"><label>Your plan<select id="filterStrategy">${options([['all','All plans'],...planChoices],filters.strategy)}</select></label><label>In-game hour<select id="filterTime">${options([['all','Any time'],...Array.from({length:24},(_,i)=>[String(i),hour(i)])],filters.time)}</select></label><label>Sort zones<select id="filterSort">${options([['route','Route first'],['males','Most males'],['species','Animal name']],filters.sort)}</select></label>${button('Reset filters','filters-reset','','subtle')}<p class="muted">Gold names mark species with a Great One variant.</p></div></details></div>`;}
