function zoneList(page){
 const cards=page.zones.map(z=>`<button class="zone-card ${z.id===selectedZone?'selected':''}" data-action="zone-select" data-discovery="${isUndiscoveredZone(z)?'undiscovered':'known'}" data-id="${esc(z.id)}" aria-pressed="${z.id===selectedZone}"><div class="zone-title"><strong>${(z.annotation?.name?esc(z.annotation.name):speciesName(z.species,z.speciesKey))}</strong><span class="animal-count">${z.males==null?'—':z.males}<small>M</small></span></div><div class="zone-subtitle"><span class="need-dot ${esc(z.need)}"></span>${esc(z.need)} <span>${formatZoneHours(z.start,z.end)}</span></div><div class="zone-meta"><span>${isUndiscoveredZone(z)?'Undiscovered area · ':''}${Math.round(z.x)} / ${Math.round(z.z)}</span><span>${state.route.includes(z.id)?'Stop '+(state.route.indexOf(z.id)+1):esc(planLabel(z.annotation?.strategy))}</span></div></button>`).join('');
 if(!page.total)return '<div class="empty"><h3>No matching zones</h3><p>Reset the filters to show available zones. Hidden zones require spoilers and a matching reference.</p></div>';
 const controls=page.pageCount>1?`<div class="zone-page-controls" role="group" aria-label="Zone list pages"><button class="button small" data-action="zone-page-previous" ${page.hasPrevious?'':'disabled'}>Previous</button><span>Page ${page.page+1} of ${page.pageCount}</span><button class="button small" data-action="zone-page-next" ${page.hasNext?'':'disabled'}>Next</button></div>`:'';
 return (page.pinnedId?'<p class="zone-pinned-note">Selected map zone shown first</p>':'')+cards+controls;
}
function updateZoneSummary(zones){const summary=$('#zoneSummary');if(!summary)return;summary.hidden=filters.species==='all'||huntSpeciesLoading||huntSpeciesError;if(summary.hidden)return;const undiscovered=zones.filter(isUndiscoveredZone).length;$('#knownZonesCount').textContent=undiscovered?`${fmt(zones.length-undiscovered)} known · ${fmt(undiscovered)} undiscovered`:fmt(zones.length);}
