 updatePressureControls();updateMapRouteSummary();
 updateZoneSummary(zones);$('#equipmentCount').textContent=fmt(state.equipment.length);
 $('#mapCredit').innerHTML=state.settings.terrain?'Map imagery: <a href="https://mathartbang.com/deca/hp/" target="_blank" rel="noopener noreferrer">DECA</a> · places are map references.':`Coordinate map · ${button('Enable terrain','terrain','','small subtle')}`;
 updateZoneList(zones);drawDetail();highlightAnimalPickers();connectionState(connectionReady);
 if(pendingMapZone){const id=pendingMapZone;pendingMapZone=null;if(state.zones.some(zone=>zone.id===id))chooseZone(id,{focusMap:true});else toast('This zone is not available in the current save.');}
